from demo.course import Course

def test_Course_is_full__unit_1():
    # Not full when no students and capacity > 0
    course = Course("Math", capacity=5)
    assert course.is_full() is False

def test_Course_is_full__unit_2():
    # Full when number of students equals capacity
    course = Course("Science", capacity=3)
    course.students = ["Alice", "Bob", "Charlie"]
    assert course.is_full() is True

def test_Course_is_full__unit_3():
    # Edge case: capacity zero always full
    course = Course("Art", capacity=0)
    assert course.is_full() is True
